mapper.select:
SELECT distinct MST_CFETS_CUSTOMER_TRADER.TRADER_ID id, MST_CFETS_CUSTOMER_TRADER.TRADER_NAME text, MST_CFETS_CUSTOMER_TRADER.MPARTY_ID parentId FROM (SELECT MST_CFETS_CUSTOMER_TRADER.TRADER_ID, MST_CFETS_CUSTOMER_TRADER.TRADER_NAME, MST_CFETS_CUSTOMER_TRADER.MPARTY_ID FROM MST_CFETS_CUSTOMER_TRADER INNER JOIN( SELECT nvl(t2.mparty_id,t1.party_id) PARTY_ID from MST_CFETS_CUSTOMER_INFO t1 LEFT JOIN MST_CFETS_CUSTOMER_RELA t2 on t1.party_id = t2.sparty_id WHERE 1 = 1
AND t1.PARTY_ID = #{mySide}
AND t1.PARTY_ID = #{counterId}
) t3 on MST_CFETS_CUSTOMER_TRADER.PARTY_ID = t3.PARTY_ID ) MST_CFETS_CUSTOMER_TRADER WHERE 1 = 1
AND (MST_CFETS_CUSTOMER_TRADER.TRADER_ID like concat('%',concat(#{param},'%')) or MST_CFETS_CUSTOMER_TRADER.TRADER_NAME like concat('%',concat(#{param},'%')))
AND (MST_CFETS_CUSTOMER_TRADER.TRADER_ID like concat('%',concat(#{search},'%')) or MST_CFETS_CUSTOMER_TRADER.TRADER_NAME like concat('%',concat(#{search},'%')))
AND MST_CFETS_CUSTOMER_TRADER.TRADER_ID = #{initValue}

        SELECT DISTINCT
            A.PORTFOLIO_ID id,
            A.PORTFOLIO_NAME text,
            B.IS_GUARANTEE object,
            B.VALUATION_METHOD col
        FROM PTL_PORTFOLIO A
        LEFT JOIN PA_PTL_PORTFOLIO B
          ON A.PORTFOLIO_ID = B.PORTFOLIO_ID
        INNER JOIN PTL_PORTFOLIO_AUTHORITY C
        ON A.PORTFOLIO_ID = C.PORTFOLIO_ID
        AND C.USER_ID = #{userId}
        LEFT JOIN IBU_PORTFOLIO_ACCT_RELA D
          ON A.PORTFOLIO_ID = D.PORTFOLIO_ID


                (A.PORTFOLIO_ID LIKE CONCAT('%', CONCAT(#{search}, '%'))
                OR
                A.PORTFOLIO_NAME LIKE CONCAT('%', CONCAT(#{search}, '%'))
                )


				AND (A.PORTFOLIO_ID in

					#{item}
				)





                AND A.PORTFOLIO_TYPE = #{portfolioType}


                AND A.PORTFOLIO_TYPE = #{portType}


                AND D.PARTY_ID = #{mySide}

       /*SELECT SYS_USER.USER_NAME userName, SYS_USER_ADD.IBU_TRADER ibuTrader*/
		SELECT SYS_USER_ADD.IBU_TRADER ibuTrader
         FROM SYS_USER, SYS_USER_ADD
        WHERE SYS_USER.USER_ID = SYS_USER_ADD.USER_ID

        		AND SYS_USER.USER_NAME = #{loginUserId}


        		AND SYS_USER_ADD.IBU_TRADER = #{ibuTrader}

SELECT SUM(TEMP.SHARE_AMT) SHARE_AMT
FROM (SELECT WFL_IBU_QUOTE_BOND2.SHARE_AMT
      FROM WFL_IBU_QUOTE_BOND2

         1 = 1

           AND WFL_IBU_QUOTE_BOND2.ENTRUST_ID = #{entrustId} 


           AND WFL_IBU_QUOTE_BOND2.QUOTE_ID != #{quoteId} 


    UNION ALL
    SELECT IBU_QUOTE_BOND.SHARE_AMT
      FROM IBU_QUOTE_BOND
     WHERE (IBU_QUOTE_BOND.TRADE_STATUS NOT IN ('15', '06', '08') 
           OR IBU_QUOTE_BOND.TRADE_STATUS IS NULL)

       AND IBU_QUOTE_BOND.ENTRUST_ID = #{entrustId} 


       AND IBU_QUOTE_BOND.QUOTE_ID != #{quoteId} 

    ) TEMP

SELECT DISTINCT ENTRUST_ID id, ENTRUST_ID text FROM ETR_ENTRUST
ENTRUST_ID LIKE CONCAT('%', CONCAT(#{search}, '%'))
AND ENTRUST_ID = #{initValue}
AND FINPROD_TYPE2 = #{finprodType2}

        SELECT V.SEC_ACCT_ID
          FROM PTL_SEC_ACCT PSA, STL_SEC_ACCT_INFO V
          LEFT JOIN FIN_PRODUCT R
		ON R.REGIST_ORG = V.REGIST_ORG
	 WHERE PSA.ACCT_NO = V.SEC_ACCT_ID
	   AND V.SEC_ACCT_TYPE = 'SEC'
	   AND V.TRADE_PLACE = #{tradeMarket}
	   AND PSA.PORTFOLIO_ID = #{portfolioId}
	   AND R.FINPROD_ID = #{finprodId}
